import matplotlib.pyplot as plt


def plot_gambler_policy(pi):
    # 1. Extract the states (Capital) and the best stake for each
    # We sort the keys to ensure the graph goes from $1 to $99
    sorted_capitals = sorted([s for s in pi.keys() if 0 <= s <= 100])

    stakes = []
    for s in sorted_capitals:
        # Find the action with the highest probability in the sub-dictionary
        # This handles the {stake: probability} structure
        stakes.append(min([i for i, p in pi[s].items() if p == max(pi[s].values())]))

    # 2. Create the plot
    plt.figure(figsize=(12, 6))

    # We use a step plot or bar chart to show the discrete nature of the stakes
    plt.bar(sorted_capitals, stakes, width=1.0, color='royalblue', edgecolor='white', linewidth=0.1)

    # 3. Formatting
    plt.title("Gambler's Optimal Policy (Stake per Capital Level)", fontsize=14)
    plt.xlabel("Capital ($)", fontsize=12)
    plt.ylabel("Stake ($)", fontsize=12)

    # Add a grid for better readability of the "spikes"
    plt.grid(True, linestyle='--', alpha=0.6)

    # Set axis limits to focus on the 1-99 range
    plt.xlim(0, 100)
    plt.xticks(range(0, 101, 10))

    plt.show()

